/** What a request that threw says: it didn't arrive. */
const OFFLINE = 'Check your connection and try again.'

/**
 * Runs a request and reads a throw as a refusal with `message`: a refusal resolves, so a throw
 * means the request didn't arrive.
 */
async function attempt<Result>(
  run: () => Result | Promise<Result>,
  message = OFFLINE,
): Promise<Result | { message: string; status: 'error' }> {
  try {
    return await run()
  } catch {
    return { message, status: 'error' }
  }
}

export { attempt, OFFLINE }
